<div class="toolbar"><p class="muted"><?= e($total) ?> students · organized, searchable and secure</p><?php if(Auth::can('students.write')): ?><a class="button primary" href="<?= e(url('student-form')) ?>">＋ Register student</a><?php endif ?></div><section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="students"><?php field('q','Search students','search',$_GET['q']??'',false); selectField('class_id','Class','classes',$_GET['class_id']??'',false); selectField('student_type_id','Student type','student_types',$_GET['student_type_id']??'',false); ?><button class="button" type="submit">Search</button><a class="text-link" href="<?= e(url('students')) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Student</th><th>Admission no.</th><th>Class / stream</th><th>Student type</th><th>Academic year</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows) emptyRow(7); foreach($rows as $s): ?><tr><td><div class="person"><span class="avatar soft"><?= e(substr($s['first_name'],0,1).substr($s['last_name'],0,1)) ?></span><strong><?= e($s['first_name'].' '.$s['last_name']) ?></strong></div></td><td><?= e($s['admission_number']) ?></td><td><?= e($s['class_name']) ?><small><?= e($s['stream_name']) ?></small></td><td><span class="badge <?= $s['requires_boarding']?'boarding':'neutral' ?>"><?= e($s['type_name']) ?></span></td><td><?= e($s['year_name']) ?></td><td><?php badge($s['status']); ?></td><td><a href="<?= e(url('student',['id'=>$s['id']])) ?>">View →</a></td></tr><?php endforeach ?></tbody></table></div><?php pagination($page,$page*25<$total); ?></section>
